import { TestBed } from '@angular/core/testing';

import { AuthService } from './auth.service';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';

describe('AuthService', () => {
  let service: AuthService;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [AuthService],
    });

    service = TestBed.inject(AuthService);
    httpMock = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('should log in a user and store token in localStorage', () => {
    const mockResponse = { token: 'test-jwt-token' };

    service.login('test@example.com', 'password123').subscribe(response => {
      expect(response.token).toBe(mockResponse.token);
      expect(localStorage.getItem('authToken')).toBe(mockResponse.token);
    });

    const req = httpMock.expectOne('http://localhost:8080/api/auth/login');
    expect(req.request.method).toBe('POST');
    req.flush(mockResponse);
  });

  it('should log out a user and remove token from localStorage', () => {
    localStorage.setItem('authToken', 'test-jwt-token'); // Set mock token
    service.logout();
    expect(localStorage.getItem('authToken')).toBeNull();
  });
});
